WITH RECURSIVE n(i) AS (SELECT 1 UNION ALL SELECT i+1 FROM n WHERE i<500), t AS MATERIALIZED (SELECT abs(random())%5 AS a, abs(random())%100 AS b, abs(random())%5 AS u, abs(random())%604800 AS s FROM n) INSERT INTO eventos_login (data_hora, ip_origem, usuario, resultado) SELECT datetime('2026-11-10 00:00:00', '+' || s || ' seconds'), CASE a WHEN 0 THEN '203.0.113.50' WHEN 1 THEN '203.0.113.50' WHEN 2 THEN '198.51.100.23' WHEN 3 THEN '192.0.2.15' ELSE '192.0.2.10' END, CASE WHEN a<3 THEN CASE u WHEN 0 THEN 'root' WHEN 1 THEN 'admin' WHEN 2 THEN 'ubuntu' WHEN 3 THEN 'test' ELSE 'oracle' END ELSE 'yuri' END, CASE WHEN (a<3 AND b<2) OR (a>=3 AND b<85) THEN 'sucesso' ELSE 'falha' END FROM t;
